        if len(parts) != 2:
            raise ValueError(
                "Incorrect --line-ranges format, expect 'START-END', found"
                f" {lines_str!r}"
            )
        try:
            start = int(parts[0])
            end = int(parts[1])
        except ValueError:
            raise ValueError(
                "Incorrect --line-ranges value, expect integer ranges, found"
                f" {lines_str!r}"
            ) from None
        else:
            if start < 1 or end < 1:
                raise ValueError(
                    "Incorrect --line-ranges value, "
                    f"expect positive integers, found {lines_str!r}"
                )
            if start > end:
                raise ValueError(
