def _chunk_iter(
    text: str, chunk_size: int
) -> Iterable[tuple[str, int]]:  # pragma: no cover
    offset = len(text)
    while True:
        offset -= chunk_size * 1024
        if offset <= 0:
            break
        yield (text[offset:], offset)
    yield (text, 0)

